<body>
    <div class="app-container">
        <div class="sidebar" id="sidebar">
            <div class="sidebar-header">
                <h1>Neural Search</h1>
            </div>
            <div class="mode-selector">
                <button class="mode-btn active" data-mode="normal">
                    <span class="mode-icon">💬</span>
                    <span>Normal Mode</span>
                </button>
                <button class="mode-btn" data-mode="research">
                    <span class="mode-icon">🔬</span>
                    <span>Research Mode</span>
                </button>
            </div>
            <div class="chat-history" id="chatHistory">
                <!-- Chat history items will be populated here -->
            </div>
        </div>

        <div class="main-content">
            <div class="header">
                <h2 class="header-title" id="headerTitle">Normal Mode - 100 Sources</h2>
                <div class="model-selector">
                    <div class="model-tag active" data-model="cerebras">Cerebras GPT-OSS</div>
                    <div class="model-tag" data-model="grok3">Grok 3</div>
                    <div class="model-tag" data-model="grok4">Grok 4</div>
                    <button class="action-btn" onclick="toggleSettings()">⚙️</button>
                </div>
            </div>

            <div class="chat-container" id="chatContainer">
                <!-- Messages will be populated here -->
            </div>

            <div class="input-container">
                <div class="input-wrapper">
                    <textarea 
                        class="input-field" 
                        id="inputField" 
                        placeholder="Ask me anything..." 
                        rows="1"
                    ></textarea>
                    <div class="input-actions">
                        <button class="action-btn" id="sendBtn" onclick="sendMessage()">
                            <span>▲</span>
                        </button>
                    </div>
                </div>
            </div>
        </div>

        <div class="settings-panel" id="settingsPanel">
            <div class="settings-section">
                <h3 class="settings-title">API Keys</h3>
                <div class="setting-item">
                    <label class="setting-label">Cerebras API Key</label>
                    <input type="password" class="setting-input" id="cerebrasKey" placeholder="Enter Cerebras API key">
                </div>
                <div class="setting-item">
                    <label class="setting-label">XAI API Key</label>
                    <input type="password" class="setting-input" id="xaiKey" placeholder="Enter XAI API key">
                </div>
                <div class="setting-item">
                    <label class="setting-label">Exa API Key</label>
                    <input type="password" class="setting-input" id="exaKey" placeholder="Enter Exa API key">
                </div>
            </div>

            <div class="settings-section">
                <h3 class="settings-title">Model Settings</h3>
                <div class="setting-item">
                    <label class="setting-label">Max Output Tokens</label>
                    <input type="number" class="setting-input" id="maxTokens" value="65000" min="1000" max="65000">
                </div>
                <div class="setting-item">
                    <label class="setting-label">Temperature</label>
                    <input type="number" class="setting-input" id="temperature" value="0.7" min="0" max="2" step="0.1">
                </div>
            </div>

            <div class="settings-section">
                <h3 class="settings-title">Search Settings</h3>
                <div class="setting-item">
                    <label class="setting-label">Results per Query (Normal Mode)</label>
                    <input type="number" class="setting-input" id="normalResults" value="100" min="10" max="1000">
                </div>
                <div class="setting-item">
                    <label class="setting-label">Research Duration (minutes)</label>
                    <input type="number" class="setting-input" id="researchDuration" value="60" min="5" max="180">
                </div>
            </div>
        </div>
    </div>

    <script>
        let currentMode = 'normal';
        let currentModel = 'cerebras';
        let chatHistory = [];
        let isProcessing = false;

        // Initialize app
        document.addEventListener('DOMContentLoaded', () => {
            loadSettings();
            setupEventListeners();
            autoResizeTextarea();
        });

        function setupEventListeners() {
            // Mode selector
            document.querySelectorAll('.mode-btn').forEach(btn => {
                btn.addEventListener('click', () => {
                    document.querySelectorAll('.mode-btn').forEach(b => b.classList.remove('active'));
                    btn.classList.add('active');
                    currentMode = btn.dataset.mode;
                    updateHeaderTitle();
                });
            });

            // Model selector
            document.querySelectorAll('.model-tag').forEach(tag => {
                tag.addEventListener('click', () => {
                    document.querySelectorAll('.model-tag').forEach(t => t.classList.remove('active'));
                    tag.classList.add('active');
                    currentModel = tag.dataset.model;
                });
            });

            // Input field
            const inputField = document.getElementById('inputField');
            inputField.addEventListener('keydown', (e) => {
                if (e.key === 'Enter' && !e.shiftKey) {
                    e.preventDefault();
                    sendMessage();
                }
            });

            inputField.addEventListener('input', autoResizeTextarea);
        }

        function autoResizeTextarea() {
            const textarea = document.getElementById('inputField');
            textarea.style.height = 'auto';
            textarea.style.height = textarea.scrollHeight + 'px';
        }

        function updateHeaderTitle() {
            const title = currentMode === 'normal' 
                ? 'Normal Mode - 100 Sources' 
                : 'Research Mode - Autonomous';
            document.getElementById('headerTitle').textContent = title;
        }

        function toggleSettings() {
            const panel = document.getElementById('settingsPanel');
            panel.classList.toggle('open');
        }

        function loadSettings() {
            const settings = ['cerebrasKey', 'xaiKey', 'exaKey', 'maxTokens', 'temperature', 'normalResults', 'researchDuration'];
            settings.forEach(key => {
                const value = localStorage.getItem(key);
                if (value) {
                    document.getElementById(key).value = value;
                }
            });
        }

        function saveSettings() {
            const settings = ['cerebrasKey', 'xaiKey', 'exaKey', 'maxTokens', 'temperature', 'normalResults', 'researchDuration'];
            settings.forEach(key => {
                const value = document.getElementById(key).value;
                if (value) {
                    localStorage.setItem(key, value);
                }
            });
        }

        async function sendMessage() {
            if (isProcessing) return;

            const inputField = document.getElementById('inputField');
            const message = inputField.value.trim();

            if (!message) return;

            isProcessing = true;
            inputField.value = '';
            autoResizeTextarea();

            // Add user message
            addMessage('user', message);

            // Show thinking indicator
            const thinkingId = addThinkingIndicator();

            try {
                if (currentMode === 'normal') {
                    await processNormalMode(message, thinkingId);
                } else {
                    await processResearchMode(message, thinkingId);
                }
            } catch (error) {
                console.error('Error:', error);
                removeThinkingIndicator(thinkingId);
                addMessage('assistant', 'Sorry, an error occurred. Please check your API keys and try again.');
            }

            isProcessing = false;
        }

        async function processNormalMode(query, thinkingId) {
            // Perform Exa search with 100 results
            const searchResults = await exaSearch(query, 100);

            // Update thinking indicator
            updateThinkingIndicator(thinkingId, 'Analyzing sources...');

            // Generate response using selected model
            const response = await generateResponse(query, searchResults);

            removeThinkingIndicator(thinkingId);
            addMessage('assistant', response, searchResults);
        }

        async function processResearchMode(query, thinkingId) {
            removeThinkingIndicator(thinkingId);

            // Add research progress widget
            const progressId = addResearchProgress();

            // Start autonomous research
            const duration = parseInt(document.getElementById('researchDuration').value) * 60 * 1000;
            const startTime = Date.now();
            let totalSources = 0;
            let report = '';

            while (Date.now() - startTime < duration) {
                // Multi-model collaboration
                const cerebrasInsights = await getCerebrasInsights(query, report);
                updateResearchStep(progressId, 'Cerebras analyzing...', totalSources);

                const grokInsights = await getGrokInsights(query, report);
                updateResearchStep(progressId, 'Grok reasoning...', totalSources);

                const qwenInsights = await getQwenThinking(query, report);
                updateResearchStep(progressId, 'Qwen thinking...', totalSources);

                // Perform comprehensive Exa search
                const searchQueries = generateSearchQueries(cerebrasInsights, grokInsights, qwenInsights);
                const sources = await multiExaSearch(searchQueries);
                totalSources += sources.length;

                updateResearchProgress(progressId, totalSources, duration, startTime);

                // Synthesize findings
                report = await synthesizeReport(query, sources, cerebrasInsights, grokInsights, qwenInsights, report);

                // Check if comprehensive enough
