        async function getGrokInsights(query, context) {
            const prevModel = currentModel;
            currentModel = 'grok3';
            const result = await generateResponse(query + '\n\nContext: ' + context, []);
            currentModel = prevModel;
            return result;
        }

        async function getQwenThinking(query, context) {
            const response = await fetch('/api/qwen/thinking', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    query: query,
                    context: context
                })
            });
            return await response.json();
