        function generateSearchQueries(cerebrasInsights, grokInsights, qwenInsights) {
            // Intelligent query generation based on model insights
            const queries = [];

            // Extract key concepts from each model's insights
            const concepts = extractKeyConcepts(cerebrasInsights, grokInsights, qwenInsights);

            // Generate diverse search queries
            concepts.forEach(concept => {
                queries.push(concept);
                queries.push(`${concept} research papers`);
                queries.push(`${concept} latest developments`);
