            return queries.slice(0, 20); // Limit to 20 queries per iteration
        }

        function extractKeyConcepts(cerebras, grok, qwen) {
            // Simple keyword extraction (in production, use NLP)
            const text = cerebras + ' ' + grok + ' ' + qwen;
            const words = text.toLowerCase().match(/\b\w{5,}\b/g) || [];
            const frequency = {};

            words.forEach(word => {
                frequency[word] = (frequency[word] || 0) + 1;
            });

            return Object.entries(frequency)
                .sort((a, b) => b[1] - a[1])
                .slice(0, 10)
                .map(([word]) => word);
        }

        async function synthesizeReport(query, sources, cerebras, grok, qwen, previousReport) {
