**main.py**
```python
import os
import json
import asyncio
import time
from typing import List, Dict, Any, Optional, Union
from fastapi import FastAPI, HTTPException, Request
from fastapi.responses import HTMLResponse, StreamingResponse, JSONResponse
from fastapi.middleware.cors import CORSMiddleware
from fastapi.staticfiles import StaticFiles
from pydantic import BaseModel
import uvicorn
from cerebras.cloud.sdk import AsyncCerebras
from openai import AsyncOpenAI
from exa_py import Exa
from dotenv import load_dotenv

load_dotenv()

app = FastAPI()

app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"],
    allow_credentials=True,
    allow_methods=["*"],
    allow_headers=["*"],
)

cerebras_client = AsyncCerebras(api_key=os.getenv("CEREBRAS_API_KEY"))
xai_client = AsyncOpenAI(
    api_key=os.getenv("XAI_API_KEY"),
    base_url=""
)
exa_client = Exa(api_key=os.getenv("EXA_API_KEY"))

MODEL_CONFIG = {
    "cerebras-gpt-oss": {
        "id": "llama-3.3-70b",
        "provider": "cerebras",
        "max_tokens": 65000
    },
    "cerebras-qwen-thinking": {
        "id": "qwen-3-235b-a22b-thinking-2507",
        "provider": "cerebras",
        "max_tokens": 32000
    },
    "grok-3": {
        "id": "grok-4-fast-reasoning",
        "provider": "xai",
        "max_tokens": 131072
    },
    "grok-4": {
        "id": "grok-4-0709",
        "provider": "xai",
        "max_tokens": 256000
    }
}

class SearchRequest(BaseModel):
    query: str
    mode: str
    model: str

class ChatMessage(BaseModel):
    role: str
    content: str

async def get_ai_completion(model_key: str, messages: List[Dict[str, str]], max_tokens: int = None):
    config = MODEL_CONFIG.get(model_key)
    if not config:
        raise ValueError("Invalid model")

    tokens = max_tokens or config["max_tokens"]

    if config["provider"] == "cerebras":
        response = await cerebras_client.chat.completions.create(
            model=config["id"],
            messages=messages,
            max_tokens=tokens,
            temperature=0.7
        )
        return response.choices[0].message.content
    elif config["provider"] == "xai":
        response = await xai_client.chat.completions.create(
            model=config["id"],
            messages=messages,
            max_tokens=tokens,
            temperature=0.7
        )
        return response.choices[0].message.content
    return ""

async def perform_autonomous_research(query: str):
    yield json.dumps({"type": "status", "message": "Initializing research protocols..."}) + "\n"

    try:
        initial_search = exa_client.search_and_contents(
            query,
            type="auto",
            num_results=20,
            text=True,
            highlights=True,
            summary=True
        )
        yield json.dumps({"type": "status", "message": f"Found {len(initial_search.results)} initial sources"}) + "\n"

        context_data = []
        for res in initial_search.results:
            context_data.append(f"Title: {res.title}\nURL: {res.url}\nSummary: {res.summary or res.text[:500]}")

        aggregated_context = "\n\n".join(context_data)

        iterations = 3

        for i in range(iterations):
            yield json.dumps({"type": "status", "message": f"Running analysis iteration {i+1}/{iterations}..."}) + "\n"

            analysis_prompt = [
                {"role": "system", "content": "You are a deep research AI. Analyze the current context and identify missing information."},
                {"role": "user", "content": f"Query: {query}\n\nCurrent Context:\n{aggregated_context[:50000]}\n\nIdentify 3 new specific search queries to fill knowledge gaps."}
            ]

            new_queries_text = await get_ai_completion("cerebras-qwen-thinking", analysis_prompt, 1000)
            new_queries = [q.strip() for q in new_queries_text.split('\n') if q.strip()][:3]

            for sub_query in new_queries:
                yield json.dumps({"type": "status", "message": f"Deep diving: {sub_query}"}) + "\n"
                sub_results = exa_client.search_and_contents(
                    sub_query,
                    type="auto",
                    num_results=5,
                    text=True,
                    summary=True
                )
                for res in sub_results.results:
                    aggregated_context += f"\n\nTitle: {res.title}\nURL: {res.url}\nSummary: {res.summary or res.text[:500]}"

        yield json.dumps({"type": "status", "message": "Synthesizing final comprehensive report..."}) + "\n"

        final_prompt = [
            {"role": "system", "content": "You are an expert researcher. Write a comprehensive, academic-grade report based on the provided context. Use markdown. Cite sources."},
            {"role": "user", "content": f"Original Query: {query}\n\nResearch Context:\n{aggregated_context[:100000]}\n\nWrite a detailed report."}
        ]

        final_report = await get_ai_completion("grok-4", final_prompt, 10000)

        yield json.dumps({"type": "result", "content": final_report}) + "\n"

    except Exception as e:
        yield json.dumps({"type": "error", "message": str(e)}) + "\n"

@app.get("/")
async def read_root():
    with open("index.html", "r") as f:
        return HTMLResponse(content=f.read())

@app.get("/sw.js")
async def read_sw():
    with open("sw.js", "r") as f:
        return HTMLResponse(content=f.read(), media_type="application/javascript")

@app.get("/manifest.json")
async def read_manifest():
    with open("manifest.json", "r") as f:
        return JSONResponse(content=json.load(f))

@app.post("/api/search")
async def search(request: SearchRequest):
    if request.mode == "autonomous":
        return StreamingResponse(perform_autonomous_research(request.query), media_type="application/x-ndjson")

    try:
        search_results = exa_client.search_and_contents(
            request.query,
            type="auto",
            num_results=50,
            text=True,
            highlights=True,
            summary=True
        )

        context = "\n\n".join([f"[{i+1}] {r.title} ({r.url}): {r.summary or r.text[:300]}" for i, r in enumerate(search_results.results)])

        messages = [
            {"role": "system", "content": "You are a helpful AI assistant. Answer the user query based strictly on the provided search results. Cite sources using [1], [2] format."},
            {"role": "user", "content": f"Query: {request.query}\n\nSearch Results:\n{context}"}
        ]

        answer = await get_ai_completion(request.model, messages)

        return {
            "type": "complete",
            "content": answer,
            "sources": [{"title": r.title, "url": r.url, "id": i+1} for i, r in enumerate(search_results.results)]
        }
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))

if __name__ == "__main__":
    uvicorn.run("main:app", host="0.0.0.0", port=8000, reload=True)
```

