    <div class="container">
        <header>
            <h1>ResearchOS</h1>
        </header>

        <div class="mode-switch">
            <button class="mode-btn active" onclick="setMode('simple')">Simple</button>
            <button class="mode-btn" onclick="setMode('autonomous')">Autonomous</button>
        </div>

        <div class="controls">
            <select id="modelSelect">
                <option value="cerebras-gpt-oss">Cerebras Llama 3.3 70B</option>
                <option value="cerebras-qwen-thinking">Cerebras Qwen Thinking</option>
                <option value="grok-3">xAI Grok 3 Fast</option>
                <option value="grok-4">xAI Grok 4</option>
            </select>
        </div>

        <div class="search-box">
            <input type="text" id="queryInput" placeholder="Ask anything...">
            <button class="submit-btn" onclick="runSearch()">GO</button>
        </div>

        <div id="output"></div>
    </div>

    <script>
        let currentMode = 'simple';

        function setMode(mode) {
            currentMode = mode;
            document.querySelectorAll('.mode-btn').forEach(btn => {
                btn.classList.toggle('active', btn.innerText.toLowerCase() === mode);
            });
        }

        if ('serviceWorker' in navigator) {
            navigator.serviceWorker.register('/sw.js');
        }

        async function runSearch() {
            const query = document.getElementById('queryInput').value;
            const model = document.getElementById('modelSelect').value;
            const output = document.getElementById('output');

            if (!query) return;

            output.innerHTML = '<div class="loading">Processing...</div>';

            try {
                const response = await fetch('/api/search', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ query, mode: currentMode, model })
                });

                if (currentMode === 'autonomous') {
                    output.innerHTML = '';
                    const reader = response.body.getReader();
                    const decoder = new TextDecoder();

                    while (true) {
                        const { done, value } = await reader.read();
                        if (done) break;

                        const chunk = decoder.decode(value);
                        const lines = chunk.split('\n');

                        for (const line of lines) {
                            if (!line) continue;
                            try {
                                const data = JSON.parse(line);
                                if (data.type === 'status') {
                                    const log = document.createElement('div');
                                    log.className = 'log-entry';
                                    log.textContent = `> ${data.message}`;
                                    output.appendChild(log);
                                } else if (data.type === 'result') {
                                    const resultDiv = document.createElement('div');
                                    resultDiv.className = 'result-content';
                                    resultDiv.innerHTML = formatMarkdown(data.content);
                                    output.appendChild(resultDiv);
                                } else if (data.type === 'error') {
                                    output.innerHTML += `<div style="color:red">Error: ${data.message}</div>`;
                                }
                                output.scrollTop = output.scrollHeight;
                            } catch (e) {
                                console.error(e);
                            }
                        }
                    }
                } else {
                    const data = await response.json();
                    let html = `<div class="result-content">${formatMarkdown(data.content)}</div>`;
                    if (data.sources) {
                        html += '<div class="sources"><h3>Sources</h3>';
                        data.sources.forEach(s => {
                            html += `[${s.id}] ${s.title}`;
                        });
                        html += '</div>';
                    }
                    output.innerHTML = html;
                }
            } catch (err) {
                output.innerHTML = `<div style="color:red">Connection Error: ${err.message}</div>`;
            }
        }

        function formatMarkdown(text) {
            if (!text) return '';
            return text
                .replace(/^# (.*$)/gim, '<h1>$1</h1>')
                .replace(/^## (.*$)/gim, '<h2>$1</h2>')
                .replace(/^### (.*$)/gim, '<h3>$1</h3>')
                .replace(/\*\*(.*)\*\*/gim, '<b>$1</b>')
                .replace(/\*(.*)\*/gim, '<i>$1</i>')
                .replace(/`(.*)`/gim, 'de>$1</code>')
                .replace(/\n/gim, '<br>');
        }
    </script>
</body>
</html>
